\\nDownloading {model_id}...\", flush=True)\n    t0 = time.time()\n    ok = download_file(url, weight_file)\n    elapsed = time.time() - t0\n    if ok:\n        print(f\"  OK: {elapsed:.1f}s\", flush=True)\n    else:\n        print(f\"  FAILED after {elapsed:.1f}s\", flush=True)\n\n# Verify\nprint(\"\\n=== Verification ===\", flush=True)\nimport zipfile\nfor seed in SEEDS:\n    f = f\"{DLDIR}/seed{seed}/pytorch_model.bin\"\n    try:\n        z = zipfile.ZipFile(f)\n        entries = len(z.namelist())\n        z.close()\n        print(f\"seed{seed}: VALID ({os.path.getsize(f)/1024/1024:.1f}MB, {entries} entries)\", flush=True)\n    except FileNotFoundError:\n        print(f\"seed{seed}: MISSING\", flush=True)\n    except Exception as e:\n        print(f\"seed{seed}: CORRUPT - {e}\", flush=True)\n\nprint(\"\\nALL_DOWNLOADS_DONE\", flush=True)\nPYEOF\necho \"requests download script created\"","account":"root"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":312,"cache_read_input_tokens":160023,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":312},"output_tokens":8,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"4808dd6d-d742-4937-b2b6-6f6761510e4b","uuid":"6d599d99-e1ea-4773-9220-e469460c83cf"}
