length + (downloaded if r.status_code == 206 else 0)\n            \n            with open(dest, mode) as f:\n                last_report = time.time()\n                for chunk in r.iter_content(chunk_size=131072):\n                    f.write(chunk)\n                    downloaded += len(chunk)\n                    if time.time() - last_report > 30:\n                        pct = downloaded / total * 100 if total else 0\n                        print(f\"    {downloaded/1024/1024:.1f}/{total/1024/1024:.1f}MB ({pct:.0f}%)\", flush=True)\n                        last_report = time.time()\n            \n            print(f\"    Complete: {downloaded/1024/1024:.1f}MB\", flush=True)\n            return True\n            \n        except Exception as e:\n            print(f\"    Attempt {attempt+1} error: {type(e).__name__}: {e}\", flush=True)\n            time.sleep(15 * (attempt + 1))\n    \n    return False\n\n# Main\nprint(f\"=== START {time.strftime('%H:%M:%S')} ===\", flush=True)\n\nfor seed in SEEDS:\n    model_id = f\"EleutherAI/pythia-70m-seed{seed}\"\n    seed_dir = f\"{DLDIR}/seed{seed}\"\n    os.makedirs(seed_dir, exist_ok=True)\n    weight_file = f\"{seed_dir}/pytorch_model.bin\"\n    \n    # Check if valid\n    if os.path.exists(weight_file):\n        try:\n            z = zipfile.ZipFile(weight_file)\n            z.close()\n            print(f\"seed{seed}: Already valid\", flush=True)\n            continue\n        except:\n            pass\n    \n    # Download small files\n    for fname in [\"config.json\", \"tokenizer.json\", \"tokenizer_config.json\", \"special_tokens_map.json\", \"generation_config.json\"]:\n        dest = f\"{seed_dir}/{fname}\"\n        if not os.path.exists(dest) or os.path.getsize(dest) == 0:\n            try:\n                r = session.get(f\"https://huggingface.co/{model_id}/resolve/main/{fname}\", timeout=30, proxies=PROXY)\n                with open(dest, \"w\") as f:\n                    f.write(r.text)\n            except:\n                pass\n    \n    # Download weight\n    print(f\"\\nseed{seed}: Downloading {model_id}...\", flush=True)\n    t0 = time.time()\n    ok = download_weight(model_id, weight_file)\n    elapsed = time.time() - t0\n    \n    if ok:\n        try:\n            z = zipfile.ZipFile(weight_file)\n            z.close()\n            print(f\"seed{seed}: OK ({elapsed:.0f}s, VALID)\", flush=True)\n        except:\n            print(f\"seed{seed}: Downloaded but CORRUPT\", flush=True)\n    else:\n        print(f\"seed{seed}: FAILED ({elapsed:.0f}s)\", flush=True)\n\nprint(f\"\\n=== ALL_DONE {time.strftime('%H:%M:%S')} ===\", flush=True)\nPYEOF\necho \"70m download script ready\"","account":"root"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":1154,"cache_read_input_tokens":164005,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":1154},"output_tokens":8,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"4808dd6d-d742-4937-b2b6-6f6761510e4b","uuid":"1f61abcf-ee15-4fe5-8ed1-77f9693a1ce9"}
